import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, SendMessageParams, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

// specs/hal-engine-config-hooks/spec.md#9
const promptBuilder = new PromptBuilder({identity: 'Usage test.'});
const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'lookup-1', name: 'lookup', input: {}}};
const rounds: MessageChunk[][] = [
  [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 11, outputTokens: 2, totalTokens: 13}}],
  [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: {inputTokens: 23, outputTokens: 3, totalTokens: 26}}],
  [{type: 'stop', stopReason: 'end_turn', usage: {inputTokens: 37, outputTokens: 5, totalTokens: 42}}],
];

const scriptedProvider = (): AIProvider => {
  let round = 0;
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield* rounds[round++];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

describe('afterModelResponse usage aggregation', () => {
  it('sums reported token fields across provider rounds', async () => {
    let reported: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    };
    const registry = new ToolRegistry();
    registry.register({name: 'lookup', description: 'Looks up a value.', inputSchema: {type: 'object'}}, async () => 'found');
    const orchestrator = createChatOrchestrator(scriptedProvider(), promptBuilder, registry, {hooks});
    const session: ChatSession = {
      sessionId: 'usage-session',
      userId: 'usage-user',
      entries: [{role: 'user', content: 'Use tools.', timestamp: '2026-01-01T00:00:00.000Z'}],
    };

    await orchestrator.processMessage(session);

    expect(reported).toEqual({inputTokens: 71, outputTokens: 10, totalTokens: 81});
  });
});
EOF
